import sys
from math import sqrt

def find_wall_point(y1, y2, yw, xb, yb, r):
    def reflect_y(y):
        return y1 + (y2 - y1) * (yw - y) / (yw - y1)

    def intersects(x, y):
        dy = y - yb
        dx = x - xb
        t = dy / dx
        y_reflected = reflect_y(yb + t * dx)
        return abs(y_reflected - y) <= r

    low, high = xb, yw
    while high - low > 1e-8:
        mid = (low + high) / 2
        if intersects(mid, yw):
            high = mid
        else:
            low = mid

    return low if intersects(low, yw) else -1

